function bdclp_validate_config(C)
%BDCLP_VALIDATE_CONFIG Reject invalid timing; do not silently round cadences.
assert(isstruct(C) && strcmp(C.schema,'bdcl_position_execution_v1'), ...
    'bdclp:ConfigSchema','Use the position execution configuration.');
dt=C.clock.plant_dt_s;
assert(isscalar(dt)&&isfinite(dt)&&dt>0,'bdclp:Clock','Invalid plant step.');
names={'control_dt_s','feedback_dt_s','power_dt_s'};
for k=1:numel(names)
    v=C.clock.(names{k}); r=v/dt;
    assert(isscalar(v)&&isfinite(v)&&v>=0&&abs(r-round(r))<1e-8, ...
        'bdclp:Clock','Sampling and decision periods must align with plant steps.');
end
assert(C.clock.control_dt_s>=dt && C.clock.feedback_dt_s>=dt && C.clock.power_dt_s>=dt, ...
    'bdclp:Clock','Sampling periods must be positive.');
assert(isfield(C,'execution') && any(strcmp(C.execution.compute_mode,{'wall_time','budget'})) && ...
    isscalar(C.execution.budget_s) && isfinite(C.execution.budget_s) && C.execution.budget_s>=0 && ...
    isscalar(C.execution.deadline_s) && isfinite(C.execution.deadline_s) && C.execution.deadline_s>0, ...
    'bdclp:ExecutionClock','Declare measured online timing or an explicit nominal compute budget.');
assert(strcmp(C.execution.overrun_policy,'hold_and_skip_busy_ticks'), ...
    'bdclp:ExecutionClock','Use the declared shared overrun scheduling rule.');
assert(isfield(C,'transport') && isfinite(C.transport.baud_rate) && C.transport.baud_rate>0 && ...
    C.transport.bits_per_byte==10 && all(isfinite([C.transport.command_processing_s ...
    C.transport.feedback_processing_s C.transport.power_delay_s])) && ...
    all([C.transport.command_processing_s C.transport.feedback_processing_s C.transport.power_delay_s]>=0), ...
    'bdclp:Transport','8N1 serial transport and finite nonnegative processing times are required.');
assert(C.control.rate_min>0 && C.control.rate_min<C.control.rate_max && ...
    C.control.rate_rise_per_s>0 && C.control.rate_fall_per_s>0, ...
    'bdclp:Rate','Invalid time-scaling bounds.');
assert(isfinite(C.control.reference_samples)&&C.control.reference_samples>=9&& ...
    C.control.reference_samples==fix(C.control.reference_samples)&& ...
    isfinite(C.control.reference_search_steps)&&C.control.reference_search_steps>=2&& ...
    C.control.reference_search_steps==fix(C.control.reference_search_steps)&& ...
    isfinite(C.control.reference_limit_relative_tolerance)&&C.control.reference_limit_relative_tolerance>=0, ...
    'bdclp:ReferenceLimits','Declare valid common reference transition checks.');
assert(C.power.soft_budget_W>0 && C.power.filter_tau_s>0, ...
    'bdclp:Power','Budget and filter time constant must be positive.');
assert(all(isfinite([C.control.max_position_age_s C.control.max_power_age_s])) && ...
    C.control.max_position_age_s>0 && C.control.max_power_age_s>0, ...
    'bdclp:FeedbackAge','Position and power age thresholds must be explicit and positive.');
assert(C.command.speed>=1 && C.command.speed<=4096 && C.command.speed==fix(C.command.speed) && ...
    C.command.acc>=1 && C.command.acc<=254 && C.command.acc==fix(C.command.acc), ...
    'bdclp:Command','Use nonzero SDK speed and acceleration parameters.');
assert(C.evaluation.initial_hold_s>=0 && C.evaluation.terminal_hold_s>0 && ...
    C.evaluation.max_time_s>0,'bdclp:Evaluation','Invalid evaluation durations.');
assert(isfield(C.evaluation,'completion_schema') && ...
    strcmp(C.evaluation.completion_schema,'elapsed_reference_delivered_terminal_stable_v1'), ...
    'bdclp:CompletionContract','Use the elapsed-reference, delivered-terminal-command completion contract.');
assert(isfinite(C.evaluation.noguard_rate) && C.evaluation.noguard_rate>0 && ...
    C.evaluation.noguard_rate<=C.control.rate_max, ...
    'bdclp:BaselineRate','NoGuard requested rate must fit the common allowable range.');
assert(abs(C.evaluation.initial_hold_s/dt-round(C.evaluation.initial_hold_s/dt))<1e-8, ...
    'bdclp:Clock','Initial holding duration must align with plant integration.');
assert(any(strcmp(C.learning.backend,{'transformer','mlp'})), ...
    'bdclp:LearningBackend','Select the transformer or explicit mlp baseline.');
assert(C.learning.sequence_length>=2 && C.learning.sequence_length==fix(C.learning.sequence_length) && ...
    isfinite(C.learning.sequence_dt_s) && C.learning.sequence_dt_s>0, ...
    'bdclp:Sequence','Invalid known-reference lookahead configuration.');
assert(isscalar(C.learning.dagger_rounds) && C.learning.dagger_rounds==1, ...
    'bdclp:DAgger','Use one aggregation pass per alternating update.');
assert(isscalar(C.learning.alternating_rounds) && isfinite(C.learning.alternating_rounds) && ...
    C.learning.alternating_rounds>=1 && C.learning.alternating_rounds==fix(C.learning.alternating_rounds), ...
    'bdclp:Alternation','Alternating updates must be a positive integer.');
assert(isfinite(C.learning.teacher_horizon_s) && C.learning.teacher_horizon_s>=C.clock.control_dt_s, ...
    'bdclp:TeacherHorizon','The offline prediction window must include a full decision interval.');
assert(C.learning.route_candidates>=2 && isfinite(C.learning.route_candidates) && ...
    C.learning.route_candidates==fix(C.learning.route_candidates), ...
    'bdclp:RouteCandidates','Declare at least two sampled candidate paths per task and round.');
assert(isfield(C.learning,'method_schema')&& ...
    strcmp(C.learning.method_schema,'candidate_path_observed_rate_alternating_v28_v1'), ...
    'bdclp:LearningContract','Use the r6 common path/rate alternating-learning method.');
for f={'route_prototypes','route_proposals','route_hidden_units'}
    v=C.learning.(f{1});
    assert(isscalar(v)&&isfinite(v)&&v>=1&&v==fix(v), ...
        'bdclp:RouteCandidates','Candidate learner dimensions must be positive integers.');
end
assert(all(isfinite([C.learning.learning_rate C.learning.route_learning_rate]))&& ...
    all([C.learning.learning_rate C.learning.route_learning_rate]>0), ...
    'bdclp:LearningRate','Declare separate positive feedback and path learning rates.');
assert(strcmp(C.learning.ffn_activation,'gelu')&&strcmp(C.learning.position_encoding,'none'), ...
    'bdclp:LearningContract','Use the declared GELU feedback network without explicit position encoding.');
L=C.learning.feedback_loss;
assert(strcmp(L.schema,'delayed_position_response_regularized_v1')&& ...
    strcmp(L.response_schema,'bdclp_delayed_first_action_response_v1')&& ...
    L.rate_lower==C.control.rate_min&&L.rate_upper==C.control.rate_max&& ...
    isfinite(L.response_horizon_s)&&L.response_horizon_s>=C.clock.control_dt_s, ...
    'bdclp:FeedbackLoss','Feedback regularization must match the delayed position execution and rate bounds.');
for f={'mse_weight','teacher_logit_weight','physics_weight','soft_power_weight','speed_weight','endpoint_weight','support_weight'}
    v=L.(f{1});
    assert(isscalar(v)&&isfinite(v)&&v>0,'bdclp:FeedbackLoss','Every declared loss term needs a finite positive weight.');
end
B=C.learning.teacher_successor_search;
assert(strcmp(B.schema,'bounded_first_feasible_continuation_v1')&& ...
    all(isfinite([B.local_offsets B.refine_offsets]))&& ...
    B.grid_points>=2&&B.grid_points==fix(B.grid_points)&& ...
    B.transition_refine_iterations>=0&&B.transition_refine_iterations==fix(B.transition_refine_iterations)&& ...
    B.max_candidates>=1&&B.max_candidates==fix(B.max_candidates)&& ...
    B.max_parent_candidates>=1&&B.max_parent_candidates==fix(B.max_parent_candidates), ...
    'bdclp:TeacherSearch','Use finite bounded first-feasible continuation settings.');
for f={'power','progress','tracking','smooth','reserve','terminal'}
    v=C.learning.teacher_weights.(f{1});
    assert(isscalar(v)&&isfinite(v)&&v>=0,'bdclp:TeacherWeights','Teacher weights must be finite and nonnegative.');
end
scales=[C.learning.teacher_tracking_scale_rad C.learning.teacher_velocity_scale_rad_s ...
    C.learning.teacher_terminal_window_s C.learning.teacher_progress_floor_rad_s ...
    C.learning.teacher_tau_reserve_ratio C.learning.teacher_reference_acc_reserve_ratio];
assert(all(isfinite(scales))&&all(scales>0),'bdclp:TeacherScales','Teacher scales must be finite and positive.');
assert(isfield(C.learning,'terminal_objective_schema')&& ...
    strcmp(C.learning.terminal_objective_schema,'shared_start_gate_reference_delivery_readiness_v1'), ...
    'bdclp:TerminalObjective','Declare the shared current-state gate and reference/delivery readiness objective.');
first=[C.task.seed_train C.task.seed_validation C.task.seed_test];
counts=[C.learning.train_tasks C.learning.validation_tasks C.evaluation.N];
assert(all(isfinite(first))&&all(first>=0)&&all(first==fix(first))&& ...
    all(isfinite(counts))&&all(counts>=1)&&all(counts==fix(counts))&& ...
    all(first+counts-1<2^32), ...
    'bdclp:TaskSeeds','Declare valid nonempty train, development and test seed ranges.');
for a=1:3
    for b=a+1:3
        assert(first(a)+counts(a)-1<first(b)||first(b)+counts(b)-1<first(a), ...
            'bdclp:TaskSplitOverlap','Train, development and test seed ranges must be disjoint.');
    end
end
names={'max_mean_time_delta_s','max_mean_R_soft_delta','max_mean_excess_delta_W', ...
    'max_mean_energy_delta_J','strict_time_improvement_s', ...
    'strict_excess_improvement_W','strict_energy_improvement_J'};
limits=[1e-9 1e-12 1e-9 1e-9 1e-9 1e-9 1e-9];
assert(isfield(C,'readiness')&&isstruct(C.readiness)&& ...
    all(isfield(C.readiness,[{'schema','require_all_valid'} names]))&& ...
    strcmp(C.readiness.schema,'physical_per_task_noslower_v28_v1')&& ...
    isequal(C.readiness.require_all_valid,true), ...
    'bdclp:ReadinessContract','The formal development gate requires every paired task to be valid.');
for k=1:numel(names)
    v=C.readiness.(names{k});
    assert(isnumeric(v)&&isreal(v)&&isscalar(v)&&isfinite(v)&&v>=0&&v<=limits(k), ...
        'bdclp:ReadinessContract','Development tolerances may not loosen the declared numerical tolerances.');
end
end
